"""Tests for analyze_log.py. The logs are SYNTHETIC: generated by stats_sample using
the firmware's real log formatters, so the analyser is proven to understand what the
firmware prints. They are not measurements of real hardware."""
import contextlib
import io
import os
import tempfile
import unittest

import helpers

A = helpers.load_analyzer()


def status(results, name):
    for st, n, _ in results:
        if n == name:
            return st
    raise KeyError(name)


def overall(text, minutes=30):
    return A.analyze(text, minutes)


class CleanRuns(unittest.TestCase):
    def test_clean_30_minute_run_passes_everything(self):
        results, total = overall(helpers.sample_log(31, "clean"))
        self.assertEqual(total, A.PASS, results)
        self.assertTrue(all(st == A.PASS for st, _, _ in results), results)

    def test_clean_12_hour_run_passes(self):
        results, total = A.analyze(helpers.sample_log(721, "clean"), min_minutes=720)
        self.assertEqual(total, A.PASS, results)

    def test_every_stats_line_the_firmware_prints_is_understood(self):
        text = helpers.sample_log(31, "clean")
        segments, _, _ = A.parse(text)
        self.assertEqual(sum(len(s.stats) for s in segments), 31)

    def test_ordinary_heap_jitter_is_not_a_leak(self):
        import re
        counter = [0]

        def jitter(match):
            counter[0] += 1
            return "heap_free=%d" % (230000 + (30 if counter[0] % 2 else -30))

        noisy = re.sub(r"heap_free=\d+", jitter, helpers.sample_log(31, "clean"))
        results, total = overall(noisy)
        self.assertEqual(status(results, "free heap"), A.PASS, results)

    def test_colour_codes_from_the_serial_monitor_are_ignored(self):
        coloured = "\n".join("\x1b[0;32m%s\x1b[0m" % l for l in helpers.sample_log(31).splitlines())
        self.assertEqual(overall(coloured)[1], A.PASS)


class Failures(unittest.TestCase):
    def check(self, mode, name, expected, minutes=31):
        results, total = overall(helpers.sample_log(minutes, mode))
        self.assertEqual(status(results, name), expected, "%s: %s" % (mode, results))
        if expected == A.FAIL:
            self.assertEqual(total, A.FAIL)

    def test_too_short(self):
        results, total = A.analyze(helpers.sample_log(10, "clean"), min_minutes=30)
        self.assertEqual(status(results, "duration"), A.FAIL)
        self.assertEqual(total, A.FAIL)

    def test_memory_leak_fails(self):
        self.check("leak", "free heap", A.FAIL)

    def test_slow_leak_warns_but_does_not_fail(self):
        results, total = overall(helpers.sample_log(31, "slowleak"))
        self.assertEqual(status(results, "free heap"), A.WARN)
        self.assertEqual(total, A.WARN)

    def test_fragmentation_fails(self):
        self.check("frag", "heap fragmentation", A.FAIL)

    def test_heap_low_water_mark_falling_fails(self):
        self.check("leak_lowwater", "heap low-water mark", A.FAIL)

    def test_unexpected_reboot_fails(self):
        self.check("reboot", "boot banner", A.FAIL)

    def test_brownout_reset_fails(self):
        self.check("brownout", "reset reason", A.FAIL)

    def test_crash_on_first_boot_fails(self):
        self.check("panic_first", "reset reason", A.FAIL)

    def test_firmware_stall_fails(self):
        self.check("stall", "stats cadence", A.FAIL)

    def test_frozen_display_fails(self):
        self.check("freeze", "display updating", A.FAIL)

    def test_slow_display_updates_warn_then_fail(self):
        self.check("slow_present", "display update time", A.WARN)
        self.check("very_slow_present", "display update time", A.FAIL)

    def test_render_mismatch_fails(self):
        self.check("mismatch", "render consistency", A.FAIL)

    def test_stack_exhaustion_fails(self):
        self.check("lowstack", "stack", A.FAIL)

    def test_display_init_failure_fails(self):
        self.check("display_fail", "display init", A.FAIL)

    def test_log_that_starts_mid_run_warns_only(self):
        results, total = overall(helpers.sample_log(31, "no_banner"))
        self.assertEqual(status(results, "boot banner"), A.WARN)
        self.assertEqual(total, A.WARN)

    def test_wrong_or_empty_log_fails(self):
        for text in ("", "hello\nworld\n", "[stats] uptime=ten\n"):
            self.assertEqual(A.analyze(text)[1], A.FAIL)


class CommandLine(unittest.TestCase):
    def run_main(self, text, *extra):
        with tempfile.NamedTemporaryFile("w", suffix=".log", delete=False) as f:
            f.write(text)
        try:
            with contextlib.redirect_stdout(io.StringIO()):
                return A.main([f.name] + list(extra))
        finally:
            os.unlink(f.name)

    def test_exit_codes(self):
        self.assertEqual(self.run_main(helpers.sample_log(31, "clean")), 0)
        self.assertEqual(self.run_main(helpers.sample_log(31, "slowleak")), 0)  # warnings do not fail
        self.assertEqual(self.run_main(helpers.sample_log(31, "leak")), 1)
        self.assertEqual(self.run_main(helpers.sample_log(31, "clean"), "--min-minutes", "60"), 1)
        with contextlib.redirect_stderr(io.StringIO()):
            self.assertEqual(A.main(["/nonexistent/file.log"]), 2)


if __name__ == "__main__":
    unittest.main()
